from decimal import Decimal

from django import setup
from django.conf import settings
from django.template import Context, Template
from django.template.defaultfilters import floatformat

settings.configure(
    TEMPLATES=[{\"BACKEND\": \"django.template.backends.django.DjangoTemplates\"}],
    USE_I18N=False,
)
setup()

assert floatformat(Decimal(\"555.555\"), 2) == \"555.56\"
assert floatformat(Decimal(\"42.12345678901234567890\"), 20) == \"42.12345678901234567890\"
rendered = Template('{{ value|floatformat:20 }}').render(
    Context({'value': Decimal('42.12345678901234567890')})
)
assert rendered == '42.12345678901234567890', rendered
print('floatformat direct check passed')
print(rendered)
