    filterable = False

class BlockedExpression:
    filterable = False
    def resolve_expression(self):
        return self

class AllowedExpression:
    filterable = True
    def __init__(self, children=()):
        self.children = list(children)
    def resolve_expression(self):
        return self
    def get_source_expressions(self):
        return self.children

