    raise AssertionError('Blocked expressions must still raise NotSupportedError.')

try:
    check_filterable(object(), AllowedExpression([BlockedExpression()]))
except ns['NotSupportedError']:
    pass
else:
    raise AssertionError('Nested blocked expressions must still raise NotSupportedError.')

