const path = require('path');
const fs = require('fs');
const { JSDOM } = require('jsdom');
const { compile } = require('./compiler.js');

const sampleDir = path.resolve('test/runtime/samples/component-slot-svg-namespace');
const sveltePath = process.cwd().split('\\\\').join('/');

function register(hydratable) {
  require.extensions['.svelte'] = function(module, filename) {
    const { js } = compile(fs.readFileSync(filename, 'utf8'), {
      filename,
      format: 'cjs',
      hydratable,
      accessors: true,
      sveltePath
    });
    return module._compile(js.code, filename);
  };
}

function clearSvelteCache() {
  Object.keys(require.cache)
    .filter(file => file.endsWith('.svelte'))
    .forEach(file => delete require.cache[file]);
}

function mount(hydratable) {
  clearSvelteCache();
  register(hydratable);
  const dom = new JSDOM("'`<main>${hydratable ? '"'<svg><title>hello</title><a href=\"#link\"><text>link</text></a><rect x=\"0\" y=\"0\" width=\"20\" height=\"20\"></rect></svg>' : ''}</main>"'`);
  global.window = dom.window;
