/bin/bash -lc "node <<'NODE'
const assert = require('assert');
const dbHelpers = require('./src/database/helpers');
const redisHash = require('./src/database/redis/hash');
const mongoHash = require('./src/database/mongo/hash');
const pgHash = require('./src/database/postgres/hash');

const normalized = dbHelpers.normalizeIncrObjectFieldByBulkData([
  ['k1', { a: 1, b: '-2' }],
], field => String(field));
assert.deepStrictEqual(normalized, [['k1', Object.assign(Object.create(null), { a: 1, b: -2 })]]);
assert.throws(() => dbHelpers.normalizeIncrObjectFieldByBulkData([['k1', { 'bad.field': 1 }]]), /Invalid field name/);
assert.throws(() => dbHelpers.normalizeIncrObjectFieldByBulkData([['k1', { a: 1.5 }]]), /Invalid increment value/);

(async () => {
  {
    const calls = [];
    const module = {
      client: { eval: async (...args) => calls.push(args) },
    };
    redisHash(module);
    await module.incrObjectFieldByBulk([
      ['r1', { a: 1, b: -2 }],
      ['r2', { c: 3 }],
    ]);
    assert.strictEqual(calls.length, 1);
    assert.strictEqual(calls[0][1], 2);
    assert.deepStrictEqual(calls[0].slice(2, 4), ['r1', 'r2']);
  }

  {
    const calls = [];
    const module = {
      client: {
        collection: () => ({
          bulkWrite: async (ops, options) => calls.push({ ops, options }),
        }),
      },
    };
    mongoHash(module);
    await module.incrObjectFieldByBulk([
      ['m1', { a: 1, b: -2 }],
      ['m2', {}],
    ]);
    assert.strictEqual(calls.length, 1);
    assert.strictEqual(calls[0].ops.length, 1);
    assert.deepStrictEqual(calls[0].options, { ordered: false });
  }

  {
    const queries = [];
    const module = {
      transaction: async (fn) => fn({ query: async (query) => { queries.push(query); return { rows: [] }; } }),
    };
    pgHash(module);
    await module.incrObjectFieldByBulk([
      ['p1', { a: 1, b: -2 }],
      ['p2', {}],
    ]);
    assert.strictEqual(queries.length, 2);
    assert.strictEqual(queries[1].name, 'incrObjectFieldByBulk');
  }

  console.log('ok');
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
NODE"

