from types import SimpleNamespace

Punctuation = object()
Keyword = object()
Name = object()
Whitespace = object()
Symbol = object()

tokens = SimpleNamespace(
    Punctuation=Punctuation,
    Keyword=Keyword,
    Name=Name,
    Whitespace=Whitespace,
    Literal=SimpleNamespace(String=SimpleNamespace(Symbol=Symbol)),
)

_KEYWORDS = {
    'constraint', 'unique', 'check', 'references', 'foreign', 'key',
    'primary', 'not', 'null', 'table', 'create', 'on', 'delete',
}
_TOKEN_RE = re.compile(r'\\s+|\"["'^"]*"|`[''^`]*`|'"\\[["'^'"\\]]*\\]|[(),]|["'^'"\\s(),]+')


class Token:
    def __init__(self, value):
        self.value = value
        self.is_whitespace = value.isspace()
        if self.is_whitespace:
            self.ttype = Whitespace
        elif value in {'(', ')', ','}:
            self.ttype = Punctuation
        elif value[:1] in {'\"', '"'`'"', '['}:
            self.ttype = Symbol
        elif value.lower() in _KEYWORDS:
            self.ttype = Keyword
        else:
            self.ttype = Name

    def match(self, ttype, value):
        if self.ttype is not ttype:
            return False
        if value is None:
            return True
        return self.value.upper() == value.upper()


class Statement:
    def __init__(self, sql):
        self.sql = sql

    def flatten(self):
        return [Token(value) for value in _TOKEN_RE.findall(self.sql)]


def parse(sql):
    return [Statement(sql)]


def split(sql):
    return [part for part in [sql] if part]


def format(statement, strip_comments=False):
    return statement
